export type AccordPluginPdas = {
  pauseState: typeof findPauseStatePda;
  appealBond: typeof findAppealBondPda;
  dispute: typeof findDisputePda;
  subaccord: typeof findSubaccordPda;
  pendingUpdate: typeof findPendingUpdatePda;
  jurorStake: typeof findJurorStakePda;
  programIdentity: typeof findProgramIdentityPda;
  round: typeof findRoundPda;
};

export type AccordPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function accordProgram() {
  return <T extends AccordPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { accord: AccordPlugin }> => {
    return extendClient(client, {
      accord: <AccordPlugin>{
        accounts: {
          appealBond: addSelfFetchFunctions(client, getAppealBondCodec()),
          dispute: addSelfFetchFunctions(client, getDisputeCodec()),
          jurorStake: addSelfFetchFunctions(client, getJurorStakeCodec()),
          pauseState: addSelfFetchFunctions(client, getPauseStateCodec()),
          pendingUpdate: addSelfFetchFunctions(client, getPendingUpdateCodec()),
          round: addSelfFetchFunctions(client, getRoundCodec()),
          subaccord: addSelfFetchFunctions(client, getSubaccordCodec()),
        },
        instructions: {
          appeal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAppealInstructionAsync(input),
            ),
          cancelDispute: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelDisputeInstructionAsync(input),
            ),
          claimAppealRefund: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimAppealRefundInstructionAsync(input),
            ),
          commit: (input) =>
            addSelfPlanAndSendFunctions(client, getCommitInstruction(input)),
          commitVrfCallback: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCommitVrfCallbackInstruction(input),
            ),
          createDispute: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateDisputeInstructionAsync(input),
            ),
          createSubaccord: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateSubaccordInstructionAsync(input),
            ),
          drawSeat: (input) =>
            addSelfPlanAndSendFunctions(client, getDrawSeatInstruction(input)),
          executeSubaccordUpdate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecuteSubaccordUpdateInstruction(input),
            ),
          executeUnpause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecuteUnpauseInstructionAsync(input),
            ),
          finalizeDispute: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFinalizeDisputeInstruction(input),
            ),
          finalizeRound: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFinalizeRoundInstruction(input),
            ),
          getRuling: (input) =>
            addSelfPlanAndSendFunctions(client, getGetRulingInstruction(input)),
          health: (input) =>
            addSelfPlanAndSendFunctions(client, getHealthInstruction(input)),
          initializePause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializePauseInstructionAsync(input),
            ),
          pause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPauseInstructionAsync(input),
            ),
          proposeSubaccordUpdate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeSubaccordUpdateInstructionAsync(input),
            ),
          proposeUnpause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeUnpauseInstructionAsync(input),
            ),
          pruneJuror: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPruneJurorInstructionAsync(input),
            ),
          reclaimSlot: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReclaimSlotInstruction(input),
            ),
          reconcileStake: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReconcileStakeInstruction(input),
            ),
          redraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedrawInstructionAsync(input),
            ),
          requestVrf: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestVrfInstructionAsync(input),
            ),
          requestWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestWithdrawInstructionAsync(input),
            ),
          reveal: (input) =>
            addSelfPlanAndSendFunctions(client, getRevealInstruction(input)),
          settleRound: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleRoundInstructionAsync(input),
            ),
          stake: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getStakeInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
          withdrawFees: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawFeesInstructionAsync(input),
            ),
        },
        pdas: {
          pauseState: findPauseStatePda,
          appealBond: findAppealBondPda,
          dispute: findDisputePda,
          subaccord: findSubaccordPda,
          pendingUpdate: findPendingUpdatePda,
          jurorStake: findJurorStakePda,
          programIdentity: findProgramIdentityPda,
          round: findRoundPda,
        },
        identifyAccount: identifyAccordAccount,
        identifyInstruction: identifyAccordInstruction,
        parseInstruction: parseAccordInstruction,
      },
    });
  };
}
